import json
from itertools import combinations
from hypothesis import strategies as st


@st.composite
def gen(draw):
    n = draw(st.integers(2, 8))
    alphabet = draw(st.sampled_from(["ab", "abc"]))
    word1 = draw(st.text(alphabet=alphabet, min_size=n, max_size=n))
    m = draw(st.integers(1, n - 1))
    mode = draw(st.integers(0, 2))
    if mode == 0:
        # random word2 over the same alphabet
        word2 = draw(st.text(alphabet=alphabet, min_size=m, max_size=m))
    elif mode == 1:
        # word2 close to a subsequence of word1 (often almost-equal cases)
        idx = sorted(draw(st.lists(st.integers(0, n - 1), min_size=m, max_size=m, unique=True)))
        chars = [word1[i] for i in idx]
        pos = draw(st.integers(0, m - 1))
        chars[pos] = draw(st.sampled_from(list(alphabet)))
        word2 = "".join(chars)
    else:
        # edge: all-equal strings
        c = draw(st.sampled_from(list(alphabet)))
        word1 = c * n
        word2 = draw(st.sampled_from([c * m, "".join(draw(st.sampled_from(list(alphabet))) for _ in range(m))]))
    return json.dumps(word1) + "\n" + json.dumps(word2) + "\n"


def validate(inp):
    try:
        lines = inp.strip("\n").split("\n")
        if len(lines) != 2:
            return False
        w1 = json.loads(lines[0])
        w2 = json.loads(lines[1])
    except Exception:
        return False
    if not isinstance(w1, str) or not isinstance(w2, str):
        return False
    if not (1 <= len(w2) < len(w1) <= 3 * 10**5):
        return False
    if not all('a' <= ch <= 'z' for ch in w1 + w2):
        return False
    return True


def ref(inp):
    lines = inp.strip("\n").split("\n")
    word1 = json.loads(lines[0])
    word2 = json.loads(lines[1])
    n, m = len(word1), len(word2)
    # Enumerate index sequences in lexicographic order (combinations yields
    # sorted tuples in lexicographic order); return the first valid one.
    for seq in combinations(range(n), m):
        mismatches = 0
        for k in range(m):
            if word1[seq[k]] != word2[k]:
                mismatches += 1
                if mismatches > 1:
                    break
        if mismatches <= 1:
            return json.dumps(list(seq))
    return json.dumps([])
